69	/// Find the longest consecutive run of `fence_char` in the code block's content.
70	fn longest_fence_char_sequence(node: &MdFencedCodeBlock, fence_char: char) -> usize {
71	    let content = node.content();
72	    let mut max_len = 0usize;
73	
74	    for item in content.iter() {
75	        if let Some(textual) = item.as_md_textual()
76	            && let Ok(token) = textual.value_token()
77	        {
78	            let mut consecutive_count = 0usize;
79	            for ch in token.text().chars() {
80	                if ch == fence_char {
81	                    consecutive_count += 1;
82	                    max_len = max_len.max(consecutive_count);
83	                } else {
84	                    consecutive_count = 0;
85	                }
86	            }
87	        }
88	    }
89	
90	    max_len
