7	#[derive(Debug, Clone, Default)]
8	pub(crate) struct FormatMdFencedCodeBlock;
9	impl FormatNodeRule<MdFencedCodeBlock> for FormatMdFencedCodeBlock {
10	    fn fmt_fields(&self, node: &MdFencedCodeBlock, f: &mut MarkdownFormatter) -> FormatResult<()> {
11	        let MdFencedCodeBlockFields {
12	            l_fence,
13	            r_fence,
14	            r_fence_indent,
15	            content,
16	            code_list,
17	            indent,
18	        } = node.as_fields();
19	
20	        let l_fence = l_fence?;
21	
22	        // Fenced code block delimiters are always normalized to backtick
23	        // style, regardless of whether the source used backticks or tildes
24	        // (`~~~`). CommonMark §4.5 permits both, but the formatter emits a
25	        // single canonical style.
26	        let fence_char = '`';
27	
28	        // Compute the minimum fence length needed (CommonMark §4.5).
29	        // The fence must be strictly longer than any backtick sequence in the
30	        // content, otherwise the inner sequence would be parsed as a closing
31	        // fence. E.g. if the content contains ``` (3 backticks), the outer
32	        // fence needs at least 4. Only backtick runs are counted because the
33	        // output always uses backticks — tilde runs never conflict.
34	        let max_inner = longest_fence_char_sequence(node, fence_char);
35	        let fence_len = (max_inner + 1).max(3);
36	        let normalized_fence: String = std::iter::repeat_n(fence_char, fence_len).collect();
37	
38	        // Build the info string (language/metadata tag) from the code name
39	        // list. Leading and trailing whitespace is trimmed so the info string
40	        // sits immediately after the fence characters, while the internal
41	        // structure (commas, multiple space-separated values) is preserved.
42	        let code_names: Vec<_> = code_list
43	            .into_iter()
44	            .filter_map(|item| Some((item.clone(), item.value_token().ok()?)))
45	            .collect();
46	        let raw_info: String = code_names
47	            .iter()
48	            .map(|(_, token)| token.text_trimmed())
49	            .collect();
50	        let info_string = raw_info.trim();
51	
52	        write!(
53	            f,
54	            [
55	                indent.format(),
56	                format_replaced(
57	                    &l_fence,
58	                    &text(&normalized_fence, l_fence.text_trimmed_range().start())
59	                ),
60	            ]
61	        )?;
62	
63	        // Emit the trimmed info string immediately after the fence. Every
64	        // code name token is tracked (replaced or removed) so the formatter's
65	        // token bookkeeping stays consistent.
66	        if let Some(((first_node, first_token), rest)) = code_names.split_first() {
67	            f.context()
68	                .comments()
69	                .mark_suppression_checked(first_node.syntax());
70	            if info_string.is_empty() {
71	                write!(f, [format_removed(first_token)])?;
72	            } else {
73	                write!(
74	                    f,
75	                    [format_replaced(
76	                        first_token,
77	                        &text(info_string, first_token.text_trimmed_range().start())
78	                    )]
79	                )?;
80	            }
81	            for (node, token) in rest {
82	                f.context()
83	                    .comments()
84	                    .mark_suppression_checked(node.syntax());
85	                write!(f, [format_removed(token)])?;
86	            }
87	        }
88	
89	        write!(
90	            f,
91	            [
92	                hard_line_break(),
93	                content
94	                    .format()
95	                    .with_options(FormatMdFormatInlineItemListOptions {
96	                        print_mode: TextPrintMode::Clean,
97	                        keep_fences_in_italics: false
98	                    }),
99	                hard_line_break(),
100	                r_fence_indent.format(),
101	            ]
102	        )?;
103	
104	        if let Ok(r_fence) = r_fence {
105	            write!(
106	                f,
107	                [format_replaced(
108	                    &r_fence,
109	                    &text(&normalized_fence, r_fence.text_trimmed_range().start())
110	                )]
111	            )?;
112	        }
113	
114	        Ok(())
115	    }
116	}
