118	/// Find the longest consecutive run of `fence_char` in the code block's content.
119	fn longest_fence_char_sequence(node: &MdFencedCodeBlock, fence_char: char) -> usize {
120	    let content = node.content();
121	    let mut max_len = 0usize;
122	
123	    for item in content.iter() {
124	        if let Some(textual) = item.as_md_textual()
125	            && let Ok(token) = textual.value_token()
126	        {
127	            let mut consecutive_count = 0usize;
128	            for ch in token.text().chars() {
129	                if ch == fence_char {
130	                    consecutive_count += 1;
131	                    max_len = max_len.max(consecutive_count);
132	                } else {
133	                    consecutive_count = 0;
134	                }
135	            }
136	        }
137	    }
138	
139	    max_len
140	}
